package com.internship.eligibility.controller;
import com.internship.eligibility.dto.EligibilityResponse;import com.internship.eligibility.entity.Internship;import com.internship.eligibility.service.InternshipService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/internships") public class InternshipController {private final InternshipService s;public InternshipController(InternshipService s){this.s=s;}@GetMapping List<Internship> all(){return s.all();}@GetMapping("/{id}") Internship one(@PathVariable Long id){return s.one(id);}@PostMapping("/{id}/check-eligibility") EligibilityResponse check(Authentication a,@PathVariable Long id){return s.check(a.getName(),id);}}
